def transform(grid):
    out = [row[:] for row in grid]
    marker_row = len(grid) - 1
    for col in (i for i, value in enumerate(grid[-1]) if value == 5):
        color = 5
        for r in range(marker_row - 1, -1, -1):
            if grid[r][col] != 0:
                color = grid[r][col]
            out[r][col] = color
    return out
